"use strict";(globalThis.webpackChunkgrc||=[]).push([[39442],{27793(e){e.exports=JSON.parse('{"citeKey":"lu2023care","slug":"lu-2023-care-bc99","title":"CARE: A Concurrency-Aware Enhanced Lightweight Cache Management Framework","authors":["X. Lu","R. Wang","X.-H. Sun"],"venue":"The 29th IEEE International Symposium on High-Performance Computer Architecture (HPCA-29), Montreal, QC, Canada, February 25 - March 01, 2023","type":"Conference","entryType":"inproceedings","date":"February, 2023","year":2023,"era":"iit","month":2,"doi":"10.1109/hpca56546.2023.10071125","abstract":"Improving cache performance is a lasting research topic. While utilizing data locality to enhance cache performance becomes more and more difficult, data access concurrency provides a new opportunity for cache performance optimization. In this work, we propose a novel concurrency-aware cache management framework that outperforms state-of-the-art locality-only cache management schemes. First, we investigate the merit of data access concurrency and pinpoint that reducing the miss rate may not necessarily lead to better overall performance. Next, we introduce the pure miss contribution (PMC) metric, a lightweight and versatile concurrency-aware indicator, to accurately measure the cost of each outstanding miss access by considering data concurrency. Then, we present CARE, a dynamic adjustable, concurrency-aware, low-overhead cache management framework with the help of the PMC metric. We evaluate CARE with extensive experiments across different application domains and show significant performance gains with the consideration of data concurrency. In a 4-core system, CARE improves IPC by 10.3% over LRU replacement. In 8 and 16-core systems where more concurrent data accesses exist, CARE outperforms LRU by 13.0% and 17.1%, respectively.","hasAbstract":true,"lede":"We propose a novel concurrency-aware cache management framework that outperforms state-of-the-art locality-only cache management schemes.","links":{"pdf":"https://grc.iit.edu/papers/2023/lu-2023-care-bc99.pdf","slides":"https://grc.iit.edu/papers/2023/lu-2023-care-bc99-slides.pdf"},"tags":["Optimization of Memory Architectures"],"_projectIds":["smc2-planning","optmem","memory-access-obfuscation"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["memory-access-obfuscation","optmem","smc2-planning"],"memberAuthors":["lu-xiaoyang","sun-xian-he"],"funding":[{"agency":"NSF","award":"CCF-2029014","projectId":"smc2-planning"},{"agency":"NSF","award":"CCF-2008907","projectId":"optmem"},{"agency":"NSF","award":"CNS-2152497","projectId":"memory-access-obfuscation"}]}')}}]);